'use client';

import React, { useState, useEffect, useCallback } from 'react';
import { useCarouselStore } from '@/store/carousel-store';
import { useCanvasStore } from '@/store/canvas-store';
import { Slide, SlideType } from '@/types/index';
import { getContentValue, getArrayContent, getContentPosition, type ElementPosition, type Alignment, type ImageConfig } from '@/types/slide-subtypes';
import { Plus, Trash2, ChevronDown, ChevronUp, Settings, Layers, Info } from 'lucide-react';
import { StyleTemplateSelector } from './StyleTemplateSelector';
import { VisualTreatmentSelector } from './VisualTreatmentSelector';
import { DecoratorControls } from './DecoratorControls';
import { CTAButtonControls } from './CTAButtonControls';
import { useDecoratorConfig } from '@/hooks/useDecoratorConfig';
import { ErrorBoundary } from '@/components/ErrorBoundary';
import { SubTypeSelector } from './SubTypeSelector';
import { ElementPositionControls } from './ElementPositionControls';
import { AlignmentControls } from './AlignmentControls';
import { ImageControls } from './ImageControls';
import { PropertyPanel } from './PropertyPanel';
import { migrateSlideToCanvas } from '@/lib/canvas/element-migration';
import { getPillarTheme } from '@/config/pillars';
import { getStyleTemplate } from '@/config/styles';
import { getDefaultSubTypeForSlideType } from '@/config/slide-subtypes';
import { TEMPLATE_DECORATOR_SUGGESTIONS } from '@/config/styles';
import { mergeDecoratorConfig, DEFAULT_DECORATOR_CONFIG } from '@/types/decorators';

interface SlideEditorProps {
  slide: Slide;
  enableCanvasMode?: boolean; // Feature flag for canvas mode
}

const slideTypes: { value: SlideType; label: string }[] = [
  { value: 'title', label: 'Title' },
  { value: 'content', label: 'Content' },
  { value: 'bullets', label: 'Bullets' },
  { value: 'quote', label: 'Quote' },
  { value: 'cta', label: 'CTA' },
  { value: 'image', label: 'Image' },
  { value: 'custom', label: 'Custom' },
];

export function SlideEditor({ slide, enableCanvasMode = false }: SlideEditorProps) {
  const { updateSlide, updateSlideStyle, updateSlideCTA, updateSlideType, updateSlideSubType, removeSlide, carousel, updateElementAlignment } = useCarouselStore();
  const { selectedIds } = useCanvasStore();

  // Collapsible sections state
  const [showAdvancedPositioning, setShowAdvancedPositioning] = useState(false);
  const [showQuickAlignment, setShowQuickAlignment] = useState(false);
  const [showTextEditingNote, setShowTextEditingNote] = useState(true);
  const [showCanvasModeInfo, setShowCanvasModeInfo] = useState(true);

  // Get decorator sources for this slide
  const { decoratorSources } = useDecoratorConfig({
    carouselConfig: carousel?.decoratorConfig,
    pillarId: carousel?.pillar || 'p1',
    slideConfig: slide.style?.decoratorConfig,
    styleTemplateId: slide.style?.template,
    applyTemplateSuggestions: true,
  });

  // Sync slide to canvas elements in canvas mode
  useEffect(() => {
    if (!enableCanvasMode) return;

    // Canvas elements are now computed from slide data
    // No need to sync them to canvas-store
  }, [slide, enableCanvasMode, carousel]);

  const handleChange = (field: string, value: string) => {
    updateSlide(slide.id, { [field]: value });
  };

  const handleElementPositionChange = (field: keyof Slide['content'], position: ElementPosition) => {
    const currentValue = slide.content[field];
    if (typeof currentValue === 'object' && currentValue !== null && 'value' in currentValue) {
      updateSlide(slide.id, {
        [field]: {
          ...currentValue,
          position,
        },
      });
    } else {
      updateSlide(slide.id, {
        [field]: {
          value: currentValue as any,
          position,
        },
      });
    }
  };

  const handleElementAlignmentChange = (field: keyof Slide['content'], alignment: Alignment) => {
    // Use the store's updateElementAlignment function directly
    // This function properly handles both plain values and positioned content
    updateElementAlignment(slide.id, field as 'headline' | 'subtext' | 'bullets' | 'quote' | 'attribution' | 'ctaText', alignment);
  };

  const handleSubTypeChange = (subTypeId: string) => {
    updateSlideSubType(slide.id, subTypeId);
  };

  const handleImageConfigChange = (imageConfig: ImageConfig) => {
    updateSlide(slide.id, { imageConfig });
  };

  const handleTemplateChange = (templateId: string) => {
    // Get template decorator suggestions
    const suggestions = TEMPLATE_DECORATOR_SUGGESTIONS[templateId];

    // Apply suggestions to decorator config
    const currentDecoratorConfig = slide.style?.decoratorConfig || {};
    const updatedDecoratorConfig = suggestions
      ? mergeDecoratorConfig(mergeDecoratorConfig(DEFAULT_DECORATOR_CONFIG, currentDecoratorConfig), suggestions)
      : currentDecoratorConfig;

    // Update both template and decorator config
    updateSlideStyle(slide.id, {
      template: templateId as any,
      decoratorConfig: updatedDecoratorConfig,
    });
  };

  const handleBulletChange = (index: number, value: string) => {
    const bullets = [...(getArrayContent(slide.content.bullets) || [])];
    bullets[index] = value;
    updateSlide(slide.id, { bullets });
  };

  const addBullet = () => {
    const bullets = [...(getArrayContent(slide.content.bullets) || []), ''];
    updateSlide(slide.id, { bullets });
  };

  const removeBullet = (index: number) => {
    const bullets = (getArrayContent(slide.content.bullets) || []).filter((_, i) => i !== index);
    updateSlide(slide.id, { bullets });
  };

  return (
    <ErrorBoundary componentName="Slide Editor">
      <div className="space-y-4 p-4 bg-white/5 rounded-xl">
        <div className="flex items-center justify-between">
          <h3 className="text-lg font-medium text-white">
            Slide {slide.order + 1}
          </h3>
          <button
            onClick={() => removeSlide(slide.id)}
            className="p-2 text-red-400 hover:text-red-300 hover:bg-red-500/10 rounded-lg transition-colors"
          >
            <Trash2 className="w-4 h-4" />
          </button>
        </div>

        {/* Slide Type Selector */}
        <div>
          <label className="block text-sm font-medium text-white/70 mb-2">
            Slide Type
          </label>
          <select
            value={slide.type}
            onChange={(e) => updateSlideType(slide.id, e.target.value as SlideType)}
            className="w-full px-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white focus:outline-none focus:border-white/40"
          >
            {slideTypes.map((type) => (
              <option key={type.value} value={type.value} className="bg-gray-900">
                {type.label}
              </option>
            ))}
          </select>
        </div>

        {/* Sub-Type Selector */}
        <SubTypeSelector
          slideType={slide.type}
          currentSubType={slide.subType}
          onChange={handleSubTypeChange}
          pillarColor={slide.style?.template ? '#00E5FF' : '#F59E0B'}
        />

{/* Canvas Mode Notice */}
        {enableCanvasMode && showCanvasModeInfo && (
          <div className="flex items-start gap-3 p-3 bg-blue-500/10 border border-blue-500/30 rounded-lg">
            <Layers className="w-5 h-5 text-blue-400 flex-shrink-0 mt-0.5" />
            <div className="flex-1">
              <p className="text-sm text-blue-300 font-medium mb-1">
                Canvas Mode Active
              </p>
              <p className="text-xs text-blue-200/70 mb-2">
                Edit elements directly on the canvas by double-clicking. Use the Property Panel to fine-tune element properties.
              </p>
              <button
                onClick={() => setShowCanvasModeInfo(false)}
                className="text-xs text-blue-400 hover:text-blue-300 underline"
              >
                Dismiss
              </button>
            </div>
          </div>
        )}

        {/* DOM Mode Notice */}
        {!enableCanvasMode && showCanvasModeInfo && (
          <div className="flex items-start gap-3 p-3 bg-amber-500/10 border border-amber-500/30 rounded-lg">
            <Settings className="w-5 h-5 text-amber-400 flex-shrink-0 mt-0.5" />
            <div className="flex-1">
              <p className="text-sm text-amber-300 font-medium mb-1">
                DOM Mode Active (Legacy)
              </p>
              <p className="text-xs text-amber-200/70 mb-2">
                Traditional editing mode with form inputs. Switch to Canvas Mode for direct canvas manipulation.
              </p>
              <button
                onClick={() => setShowCanvasModeInfo(false)}
                className="text-xs text-amber-400 hover:text-amber-300 underline"
              >
                Dismiss
              </button>
            </div>
          </div>
        )}

        {/* Canvas Mode - Property Panel Integration */}
        {enableCanvasMode && (
          <div className="border-t border-white/10 pt-4">
            <div className="flex items-center justify-between mb-3">
              <h4 className="text-sm font-medium text-white/70">Element Properties</h4>
              <Info className="w-4 h-4 text-white/40" />
            </div>
            <PropertyPanel />
          </div>
        )}

        {/* Headline */}
        {(slide.type !== 'quote') && !enableCanvasMode && (
          <div>
            <label className="block text-sm font-medium text-white/70 mb-2">
              Headline
            </label>
            <input
              type="text"
              value={getContentValue(slide.content.headline) || ''}
              onChange={(e) => handleChange('headline', e.target.value)}
              placeholder="Enter headline..."
              className="w-full px-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white placeholder-white/40 focus:outline-none focus:border-white/40"
            />
          </div>
        )}

        {/* Canvas Mode: Headline Edit Hint */}
        {enableCanvasMode && slide.type !== 'quote' && (
          <div className="p-3 bg-white/5 rounded-lg border border-white/10">
            <p className="text-xs text-white/60 mb-1">
              <strong>Headline:</strong> {getContentValue(slide.content.headline) || '(empty)'}
            </p>
            <p className="text-xs text-white/40">
              Double-click the headline on the canvas to edit it directly.
            </p>
          </div>
        )}

        {/* Subtext (for content types) */}
        {(slide.type === 'title' || slide.type === 'content' || slide.type === 'cta' || slide.type === 'custom') && !enableCanvasMode && (
          <div>
            <label className="block text-sm font-medium text-white/70 mb-2">
              Subtext
            </label>
            <textarea
              value={getContentValue(slide.content.subtext) || ''}
              onChange={(e) => handleChange('subtext', e.target.value)}
              placeholder="Enter subtext..."
              rows={3}
              className="w-full px-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white placeholder-white/40 focus:outline-none focus:border-white/40 resize-none"
            />
          </div>
        )}

        {/* Canvas Mode: Subtext Edit Hint */}
        {enableCanvasMode && (slide.type === 'title' || slide.type === 'content' || slide.type === 'cta' || slide.type === 'custom') && (
          <div className="p-3 bg-white/5 rounded-lg border border-white/10">
            <p className="text-xs text-white/60 mb-1">
              <strong>Subtext:</strong> {getContentValue(slide.content.subtext) || '(empty)'}
            </p>
            <p className="text-xs text-white/40">
              Double-click the subtext on the canvas to edit it directly.
            </p>
          </div>
        )}

        {/* Bullets */}
        {slide.type === 'bullets' && !enableCanvasMode && (
          <div>
            <label className="block text-sm font-medium text-white/70 mb-2">
              Bullet Points
            </label>
            <div className="space-y-2">
              {(getArrayContent(slide.content.bullets) || []).map((bullet, index) => (
                <div key={index} className="flex gap-2">
                  <input
                    type="text"
                    value={bullet}
                    onChange={(e) => handleBulletChange(index, e.target.value)}
                    placeholder={`Bullet ${index + 1}...`}
                    className="flex-1 px-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white placeholder-white/40 focus:outline-none focus:border-white/40"
                  />
                  <button
                    onClick={() => removeBullet(index)}
                    className="p-2 text-red-400 hover:text-red-300 hover:bg-red-500/10 rounded-lg transition-colors"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
              ))}
              <button
                onClick={addBullet}
                className="flex items-center gap-2 px-3 py-2 text-sm text-white/60 hover:text-white hover:bg-white/5 rounded-lg transition-colors"
              >
                <Plus className="w-4 h-4" />
                Add Bullet
              </button>
            </div>
          </div>
        )}

        {/* Canvas Mode: Bullets Edit Hint */}
        {enableCanvasMode && slide.type === 'bullets' && (
          <div className="p-3 bg-white/5 rounded-lg border border-white/10">
            <p className="text-xs text-white/60 mb-1">
              <strong>Bullet Points:</strong> {getArrayContent(slide.content.bullets)?.length || 0} bullets
            </p>
            <p className="text-xs text-white/40">
              Double-click the bullets on the canvas to edit them directly.
            </p>
          </div>
        )}

        {/* Quote */}
        {slide.type === 'quote' && !enableCanvasMode && (
          <>
            <div>
              <label className="block text-sm font-medium text-white/70 mb-2">
                Quote
              </label>
              <textarea
                value={getContentValue(slide.content.quote) || ''}
                onChange={(e) => handleChange('quote', e.target.value)}
                placeholder="Enter quote..."
                rows={3}
                className="w-full px-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white placeholder-white/40 focus:outline-none focus:border-white/40 resize-none"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-white/70 mb-2">
                Attribution
              </label>
              <input
                type="text"
                value={getContentValue(slide.content.attribution) || ''}
                onChange={(e) => handleChange('attribution', e.target.value)}
                placeholder="— Author Name"
                className="w-full px-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white placeholder-white/40 focus:outline-none focus:border-white/40"
              />
            </div>
          </>
        )}

        {/* Canvas Mode: Quote Edit Hint */}
        {enableCanvasMode && slide.type === 'quote' && (
          <div className="p-3 bg-white/5 rounded-lg border border-white/10">
            <p className="text-xs text-white/60 mb-1">
              <strong>Quote:</strong> {getContentValue(slide.content.quote) || '(empty)'}
            </p>
            <p className="text-xs text-white/40">
              Double-click the quote on the canvas to edit it directly.
            </p>
          </div>
        )}

        {/* Image */}
        {slide.type === 'image' && !enableCanvasMode && (
          <div>
            <label className="block text-sm font-medium text-white/70 mb-2">
              Headline (optional)
            </label>
            <input
              type="text"
              value={getContentValue(slide.content.headline) || ''}
              onChange={(e) => handleChange('headline', e.target.value)}
              placeholder="Enter headline..."
              className="w-full px-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white placeholder-white/40 focus:outline-none focus:border-white/40"
            />
          </div>
        )}

        {/* Canvas Mode: Image Edit Hint */}
        {enableCanvasMode && slide.type === 'image' && (
          <div className="p-3 bg-white/5 rounded-lg border border-white/10">
            <p className="text-xs text-white/60 mb-1">
              <strong>Headline:</strong> {getContentValue(slide.content.headline) || '(empty)'}
            </p>
            <p className="text-xs text-white/40">
              Double-click the headline on the canvas to edit it directly.
            </p>
          </div>
        )}

        {/* CTA Button Text */}
        {slide.type === 'cta' && !enableCanvasMode && (
          <div>
            <label className="block text-sm font-medium text-white/70 mb-2">
              CTA Button Text
            </label>
            <input
              type="text"
              value={getContentValue(slide.content.ctaText) || ''}
              onChange={(e) => handleChange('ctaText', e.target.value)}
              placeholder="Follow for more →"
              className="w-full px-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white placeholder-white/40 focus:outline-none focus:border-white/40"
            />
          </div>
        )}

        {/* Canvas Mode: CTA Text Edit Hint */}
        {enableCanvasMode && slide.type === 'cta' && (
          <div className="p-3 bg-white/5 rounded-lg border border-white/10">
            <p className="text-xs text-white/60 mb-1">
              <strong>CTA Button Text:</strong> {getContentValue(slide.content.ctaText) || '(empty)'}
            </p>
            <p className="text-xs text-white/40">
              Double-click the CTA button on the canvas to edit it directly.
            </p>
          </div>
        )}

        {/* Image Controls (for image slides) */}
      {slide.type === 'image' && (
        <div className="pt-4">
          {!enableCanvasMode && (
            <ImageControls
              config={slide.content.imageConfig}
              onChange={handleImageConfigChange}
              pillarColor={slide.style?.template ? '#00E5FF' : '#F59E0B'}
            />
          )}
          {enableCanvasMode && (
            <div className="p-3 bg-white/5 rounded-lg border border-white/10">
              <p className="text-xs text-white/60 mb-1">
                <strong>Image Controls:</strong> Use Property Panel
              </p>
              <p className="text-xs text-white/40">
                Select the image on the canvas to edit its properties in the Property Panel.
              </p>
            </div>
          )}
        </div>
      )}

      {/* Advanced Positioning Controls */}
      {!enableCanvasMode && (
        <div>
          <button
            type="button"
            onClick={() => setShowAdvancedPositioning(!showAdvancedPositioning)}
            className="flex items-center justify-between w-full px-3 py-2 bg-white/5 border border-white/10 rounded-lg text-white text-sm hover:bg-white/10 focus:outline-none focus:border-white/20 transition-colors"
          >
            <div className="flex items-center gap-2">
              <Settings className="w-4 h-4" />
              <span className="font-medium">Advanced Positioning</span>
            </div>
            {showAdvancedPositioning ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
          </button>

          {showAdvancedPositioning && (
            <div className="mt-4 space-y-6 p-4 bg-white/5 rounded-lg">
              {/* Headline Positioning */}
              {slide.content.headline && (
                <ElementPositionControls
                  position={getContentPosition(slide.content.headline)}
                  onChange={(position) => handleElementPositionChange('headline', position)}
                  elementName="Headline"
                />
              )}

              {/* Subtext Positioning */}
              {slide.content.subtext && (
                <ElementPositionControls
                  position={getContentPosition(slide.content.subtext)}
                  onChange={(position) => handleElementPositionChange('subtext', position)}
                  elementName="Subtext"
                />
              )}

              {/* Bullets Positioning */}
              {slide.content.bullets && (
                <ElementPositionControls
                  position={getContentPosition(slide.content.bullets)}
                  onChange={(position) => handleElementPositionChange('bullets', position)}
                  elementName="Bullet Points"
                />
              )}

              {/* Quote Positioning */}
              {slide.content.quote && (
                <ElementPositionControls
                  position={getContentPosition(slide.content.quote)}
                  onChange={(position) => handleElementPositionChange('quote', position)}
                  elementName="Quote"
                />
              )}

              {/* Attribution Positioning */}
              {slide.content.attribution && (
                <ElementPositionControls
                  position={getContentPosition(slide.content.attribution)}
                  onChange={(position) => handleElementPositionChange('attribution', position)}
                  elementName="Attribution"
                />
              )}

              {/* CTA Text Positioning */}
              {slide.content.ctaText && (
                <ElementPositionControls
                  position={getContentPosition(slide.content.ctaText)}
                  onChange={(position) => handleElementPositionChange('ctaText', position)}
                  elementName="CTA Button Text"
                />
              )}
            </div>
          )}
        </div>
      )}

      {/* Canvas Mode: Advanced Positioning Note */}
      {enableCanvasMode && (
        <div className="p-3 bg-white/5 rounded-lg border border-white/10">
          <p className="text-xs text-white/60 mb-1">
            <strong>Advanced Positioning:</strong> Use Property Panel
          </p>
          <p className="text-xs text-white/40">
            Select elements on the canvas to edit their position, size, and rotation in the Property Panel.
          </p>
        </div>
      )}

      {/* Quick Alignment Controls */}
      {!enableCanvasMode && (
        <div>
          <button
            type="button"
            onClick={() => setShowQuickAlignment(!showQuickAlignment)}
            className="flex items-center justify-between w-full px-3 py-2 bg-white/5 border border-white/10 rounded-lg text-white text-sm hover:bg-white/10 focus:outline-none focus:border-white/20 transition-colors"
          >
            <div className="flex items-center gap-2">
              <span className="font-medium">Quick Alignment</span>
            </div>
            {showQuickAlignment ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
          </button>

          {showQuickAlignment && (
            <div className="mt-4 space-y-4 p-4 bg-white/5 rounded-lg">
              {/* Headline Alignment */}
              {slide.content.headline && (
                <AlignmentControls
                  currentAlignment={getContentPosition(slide.content.headline)?.alignment}
                  onChange={(alignment) => handleElementAlignmentChange('headline', alignment)}
                  elementName="Headline"
                />
              )}

              {/* Subtext Alignment */}
              {slide.content.subtext && (
                <AlignmentControls
                  currentAlignment={getContentPosition(slide.content.subtext)?.alignment}
                  onChange={(alignment) => handleElementAlignmentChange('subtext', alignment)}
                  elementName="Subtext"
                />
              )}

              {/* Bullets Alignment */}
              {slide.content.bullets && (
                <AlignmentControls
                  currentAlignment={getContentPosition(slide.content.bullets)?.alignment}
                  onChange={(alignment) => handleElementAlignmentChange('bullets', alignment)}
                  elementName="Bullet Points"
                />
              )}

              {/* Quote Alignment */}
              {slide.content.quote && (
                <AlignmentControls
                  currentAlignment={getContentPosition(slide.content.quote)?.alignment}
                  onChange={(alignment) => handleElementAlignmentChange('quote', alignment)}
                  elementName="Quote"
                />
              )}

              {/* Attribution Alignment */}
              {slide.content.attribution && (
                <AlignmentControls
                  currentAlignment={getContentPosition(slide.content.attribution)?.alignment}
                  onChange={(alignment) => handleElementAlignmentChange('attribution', alignment)}
                  elementName="Attribution"
                />
              )}

              {/* CTA Text Alignment */}
              {slide.content.ctaText && (
                <AlignmentControls
                  currentAlignment={getContentPosition(slide.content.ctaText)?.alignment}
                  onChange={(alignment) => handleElementAlignmentChange('ctaText', alignment)}
                  elementName="CTA Button Text"
                />
              )}
            </div>
          )}
        </div>
      )}

      {/* Canvas Mode: Quick Alignment Note */}
      {enableCanvasMode && (
        <div className="p-3 bg-white/5 rounded-lg border border-white/10">
          <p className="text-xs text-white/60 mb-1">
            <strong>Quick Alignment:</strong> Use Property Panel
          </p>
          <p className="text-xs text-white/40">
            Select elements on the canvas to edit their alignment in the Property Panel.
          </p>
        </div>
      )}

      {/* Divider */}
      <div className="border-t border-white/10 my-6"></div>

      {/* Style Template Selector */}
      <StyleTemplateSelector
        value={slide.style?.template || 'minimal'}
        onChange={handleTemplateChange}
        pillarColor={slide.style?.template ? '#00E5FF' : '#F59E0B'}
        currentDecoratorConfig={slide.style?.decoratorConfig}
      />

      {/* Visual Treatment Selector */}
      <VisualTreatmentSelector
        value={slide.style?.visualTreatment}
        onChange={(visualTreatment) => updateSlideStyle(slide.id, { visualTreatment })}
        pillarColor={slide.style?.template ? '#00E5FF' : '#F59E0B'}
      />

      {/* Decorator Controls - Now available in both DOM and Canvas modes */}
      <DecoratorControls
        value={slide.style?.decoratorConfig || {}}
        onChange={(decoratorConfig) => updateSlideStyle(slide.id, { decoratorConfig })}
        pillarColor={slide.style?.template ? '#00E5FF' : '#F59E0B'}
        decoratorSources={decoratorSources}
        styleTemplateId={slide.style?.template}
      />

      {/* CTA Button Controls (for CTA slides) */}
      {slide.type === 'cta' && slide.cta && !enableCanvasMode && (
        <CTAButtonControls
          value={slide.cta}
          onChange={(cta) => updateSlideCTA(slide.id, cta)}
          pillarColor={slide.style?.template ? '#00E5FF' : '#F59E0B'}
        />
      )}
      {slide.type === 'cta' && slide.cta && enableCanvasMode && (
        <div className="p-3 bg-white/5 rounded-lg border border-white/10">
          <p className="text-xs text-white/60 mb-1">
            <strong>CTA Controls:</strong> Use Property Panel
          </p>
          <p className="text-xs text-white/40">
            Select the CTA button on the canvas to edit its properties in the Property Panel.
          </p>
        </div>
      )}
    </div>
    </ErrorBoundary>
  );
}
